#!/usr/bin/env node
/**
 * Edge-case Review — Report Renderer
 *
 * Combines .github/.pipeline-context/verify/<id>.edgecase.facts.json (script) with
 * .github/.pipeline-context/verify/<id>.edgecase.verdict.json (agent) into
 * docs/agent_output/04-verify/edgecase_<id>.md.
 *
 * Usage:
 *   node scripts/render-edgecase.js --all
 *   node scripts/render-edgecase.js --story JIRA-001
 */
const fs = require('fs');
const path = require('path');
const {
  rel, listStep1Changes, factsPathFor, verdictPathFor, reportPathFor, rewriteVerifyIndex,
} = require('./lib/verify');

const VERDICTS = ['NO_GAPS_FOUND', 'GAPS_FOUND', 'INCONCLUSIVE'];
const REQUIRED = [
  ['verdict', (v) => VERDICTS.includes(v.verdict)],
  ['plain_summary', (v) => typeof v.plain_summary === 'string' && v.plain_summary.trim()],
  ['attempted_vectors', (v) => Array.isArray(v.attempted_vectors) && v.attempted_vectors.length],
  ['reasoning', (v) => typeof v.reasoning === 'string' && v.reasoning.trim()],
];

function validate(v) {
  const missing = REQUIRED.filter(([, check]) => !check(v)).map(([k]) => k);
  if (missing.length) throw new Error(`edgecase verdict is missing required field(s): ${missing.join(', ')}. See templates/edgecase.schema.json.`);
  if (v.verdict === 'GAPS_FOUND' && (!v.gaps_found || !v.gaps_found.length)) {
    throw new Error('verdict is GAPS_FOUND but gaps_found is empty — name at least one concrete gap.');
  }
}

function render(facts, verdict) {
  const out = [];
  out.push(`# Edge-case review — ${facts.id}`);
  out.push('');
  out.push(`## ${facts.title}`);
  out.push('');
  out.push(`> ${verdict.plain_summary.trim()}`);
  out.push('');
  out.push(`_Generated by the existing-app test agent on ${new Date().toISOString().slice(0, 10)}. Facts collected ${facts.generatedAt}._`);
  out.push('');

  out.push('## At a glance', '');
  out.push('| | |', '|---|---|');
  out.push(`| **Verdict** | ${verdict.verdict} |`);
  out.push(`| **Confidence** | ${verdict.confidence || 'not stated'} |`);
  out.push(`| **Vectors attempted** | ${verdict.attempted_vectors.length} |`);
  out.push('');

  out.push('## 1. Edge cases attempted against the patched code', '');
  out.push('| Vector | Result |', '|---|---|');
  verdict.attempted_vectors.forEach((v) => out.push(`| ${v.vector} | ${v.result} |`));
  out.push('');

  if (verdict.gaps_found && verdict.gaps_found.length) {
    out.push('## 2. Gaps found', '');
    for (const g of verdict.gaps_found) out.push(`- **${g.severity}** — ${g.description}`);
    out.push('');
  }

  out.push('## Reasoning', '', verdict.reasoning.trim(), '');
  out.push('---', '', `Source development report: \`${facts.sources.devReport}\`.`, '');
  return out.join('\n');
}

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--story' || a === '-s') args.story = argv[++i];
    else if (a === '--all' || a === '-a') args.all = true;
  }
  return args;
}

function renderOne(id) {
  const ff = factsPathFor(id, 'edgecase');
  if (!fs.existsSync(ff)) throw new Error(`No facts at ${rel(ff)}. Run collect-edgecase.js --story ${id} first.`);
  const facts = JSON.parse(fs.readFileSync(ff, 'utf8'));

  const vf = verdictPathFor(id, 'edgecase');
  if (!fs.existsSync(vf)) throw new Error(`No verdict at ${rel(vf)}. Read the briefing and write it, per templates/edgecase.schema.json.`);
  const verdict = JSON.parse(fs.readFileSync(vf, 'utf8'));
  validate(verdict);

  const target = reportPathFor(id, 'edgecase');
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(facts, verdict));
  return { id, verdict: verdict.verdict, report: rel(target) };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.all) {
    const targets = listStep1Changes();
    const written = []; const skipped = [];
    for (const t of targets) {
      try { const r = renderOne(t.id); written.push(r); console.log(`${r.id.padEnd(10)} ${r.verdict.padEnd(15)} -> ${r.report}`); } catch (err) { skipped.push(t.id); console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`); }
    }
    rewriteVerifyIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s).`);
    if (skipped.length) process.exitCode = 1;
    return;
  }
  if (!args.story) throw new Error('Missing --story or --all.');
  const r = renderOne(args.story);
  rewriteVerifyIndex();
  console.log(`Edge-case review — wrote ${r.report} (${r.verdict})`);
}

try {
  main();
} catch (err) {
  console.error('Rendering failed:', err.message);
  process.exit(1);
}
